import { M3LConfigParameter } from '../parameters/index.js';
import { ConfigSchema } from './types';

/** Loads configuration from the given schema. */
export function loadConfig(schema: ConfigSchema): M3LConfigParameter[] {
  if (!schema) {
    throw 'not found';
  }
  return schema.parameters.map((p) => new M3LConfigParameter(p));
}

